CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;
CREATE TABLE "Personas" (
    "IdPersona" integer GENERATED BY DEFAULT AS IDENTITY,
    "Nombre" character varying(100) NOT NULL,
    "Apellidos" character varying(100) NOT NULL,
    "FechaNacimiento" timestamp with time zone NOT NULL,
    "Genero" text NOT NULL,
    "DUI" character varying(10) NOT NULL,
    "NIT" character varying(17) NOT NULL,
    "Email" character varying(150) NOT NULL,
    "Telefono" character varying(9) NOT NULL,
    "Direccion" character varying(250) NOT NULL,
    "NumeroAFP" character varying(20),
    "TipoAFP" character varying(50),
    CONSTRAINT "PK_Personas" PRIMARY KEY ("IdPersona")
);

CREATE TABLE "Atestados" (
    "IdAtestado" integer GENERATED BY DEFAULT AS IDENTITY,
    "IdPersona" integer NOT NULL,
    "TipoAtestado" character varying(100) NOT NULL,
    "RutaArchivo" character varying(500) NOT NULL,
    "NombreOriginalArchivo" character varying(255),
    "ExtensionArchivo" character varying(10),
    "FechaSubida" timestamp with time zone NOT NULL,
    "FechaVencimiento" timestamp with time zone,
    "SubidoPor" character varying(100),
    "Activo" boolean NOT NULL,
    "Comentarios" character varying(500),
    CONSTRAINT "PK_Atestados" PRIMARY KEY ("IdAtestado"),
    CONSTRAINT "FK_Atestados_Personas_IdPersona" FOREIGN KEY ("IdPersona") REFERENCES "Personas" ("IdPersona") ON DELETE CASCADE
);

CREATE TABLE "Directivos" (
    "IdDirectivo" integer GENERATED BY DEFAULT AS IDENTITY,
    "IdPersona" integer NOT NULL,
    "CargoDirectivo" text NOT NULL,
    "FechaInicioMandato" timestamp with time zone NOT NULL,
    "FechaFinMandato" timestamp with time zone,
    "TipoMiembro" text NOT NULL,
    CONSTRAINT "PK_Directivos" PRIMARY KEY ("IdDirectivo"),
    CONSTRAINT "FK_Directivos_Personas_IdPersona" FOREIGN KEY ("IdPersona") REFERENCES "Personas" ("IdPersona") ON DELETE CASCADE
);

CREATE TABLE "Empleados" (
    "IdEmpleado" integer GENERATED BY DEFAULT AS IDENTITY,
    "IdPersona" integer NOT NULL,
    "CodigoEmpleado" character varying(50) NOT NULL,
    "FechaContratacion" timestamp with time zone NOT NULL,
    "Puesto" character varying(100) NOT NULL,
    "Salario" numeric(18,2) NOT NULL,
    "Departamento" character varying(100) NOT NULL,
    "Estado" integer NOT NULL,
    "FechaFinContrato" timestamp with time zone,
    "MotivoFinalizacion" character varying(500),
    "TipoFinalizacion" integer,
    CONSTRAINT "PK_Empleados" PRIMARY KEY ("IdEmpleado"),
    CONSTRAINT "FK_Empleados_Personas_IdPersona" FOREIGN KEY ("IdPersona") REFERENCES "Personas" ("IdPersona") ON DELETE CASCADE
);

CREATE TABLE "NivelesEducativos" (
    "IdNivelEducativo" integer GENERATED BY DEFAULT AS IDENTITY,
    "IdPersona" integer NOT NULL,
    "GradoAcademico" character varying(100) NOT NULL,
    "Institucion" character varying(200),
    "TituloObtenido" character varying(200),
    "FechaInicio" timestamp with time zone,
    "FechaFin" timestamp with time zone,
    "Comentarios" character varying(500),
    CONSTRAINT "PK_NivelesEducativos" PRIMARY KEY ("IdNivelEducativo"),
    CONSTRAINT "FK_NivelesEducativos_Personas_IdPersona" FOREIGN KEY ("IdPersona") REFERENCES "Personas" ("IdPersona") ON DELETE CASCADE
);

CREATE TABLE "HistorialDirectivo" (
    "IdHistorialDirectivo" integer GENERATED BY DEFAULT AS IDENTITY,
    "IdDirectivo" integer NOT NULL,
    "Cargo" character varying(100) NOT NULL DEFAULT '',
    "FechaInicioMandato" timestamp with time zone NOT NULL,
    "FechaFinMandato" timestamp with time zone,
    "TipoMandato" character varying(50) NOT NULL DEFAULT '',
    "Comentarios" character varying(500),
    "RegistradoPor" character varying(255),
    "FechaRegistro" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_HistorialDirectivo" PRIMARY KEY ("IdHistorialDirectivo"),
    CONSTRAINT "FK_HistorialDirectivo_Directivos_IdDirectivo" FOREIGN KEY ("IdDirectivo") REFERENCES "Directivos" ("IdDirectivo") ON DELETE CASCADE
);

CREATE TABLE "CapacitacionesEmpleados" (
    "IdCapacitacionEmpleado" integer GENERATED BY DEFAULT AS IDENTITY,
    "IdEmpleado" integer NOT NULL,
    "NombreCurso" text NOT NULL,
    "Institucion" text,
    "FechaInicio" timestamp with time zone,
    "FechaFin" timestamp with time zone,
    "CertificadoObtenido" boolean NOT NULL,
    "RutaCertificado" text,
    "Comentarios" text,
    "EmpleadoIdEmpleado" integer NOT NULL,
    CONSTRAINT "PK_CapacitacionesEmpleados" PRIMARY KEY ("IdCapacitacionEmpleado"),
    CONSTRAINT "FK_CapacitacionesEmpleados_Empleados_EmpleadoIdEmpleado" FOREIGN KEY ("EmpleadoIdEmpleado") REFERENCES "Empleados" ("IdEmpleado") ON DELETE CASCADE
);

CREATE TABLE "EvaluacionesDesempeno" (
    "IdEvaluacion" integer GENERATED BY DEFAULT AS IDENTITY,
    "IdEmpleado" integer NOT NULL,
    "FechaEvaluacion" timestamp with time zone NOT NULL,
    "Periodo" text NOT NULL,
    "Puntuacion" numeric NOT NULL,
    "Evaluador" text,
    "Comentarios" text,
    "RutaInforme" text,
    "EmpleadoIdEmpleado" integer NOT NULL,
    CONSTRAINT "PK_EvaluacionesDesempeno" PRIMARY KEY ("IdEvaluacion"),
    CONSTRAINT "FK_EvaluacionesDesempeno_Empleados_EmpleadoIdEmpleado" FOREIGN KEY ("EmpleadoIdEmpleado") REFERENCES "Empleados" ("IdEmpleado") ON DELETE CASCADE
);

CREATE TABLE "HistorialDisciplinario" (
    "IdIncidente" integer GENERATED BY DEFAULT AS IDENTITY,
    "IdEmpleado" integer NOT NULL,
    "FechaIncidente" timestamp with time zone NOT NULL,
    "TipoIncidente" text NOT NULL,
    "Descripcion" text NOT NULL,
    "AccionTomada" text NOT NULL,
    "RutaIncidente" text,
    "RegistradoPor" text,
    "FechaRegistro" timestamp with time zone NOT NULL,
    "EmpleadoIdEmpleado" integer NOT NULL,
    CONSTRAINT "PK_HistorialDisciplinario" PRIMARY KEY ("IdIncidente"),
    CONSTRAINT "FK_HistorialDisciplinario_Empleados_EmpleadoIdEmpleado" FOREIGN KEY ("EmpleadoIdEmpleado") REFERENCES "Empleados" ("IdEmpleado") ON DELETE CASCADE
);

CREATE TABLE "HistorialPuestos" (
    "IdHistorialPuesto" integer GENERATED BY DEFAULT AS IDENTITY,
    "IdEmpleado" integer NOT NULL,
    "Puesto" character varying(100) NOT NULL,
    "FechaInicioPuesto" timestamp with time zone NOT NULL,
    "FechaFinPuesto" timestamp with time zone,
    CONSTRAINT "PK_HistorialPuestos" PRIMARY KEY ("IdHistorialPuesto"),
    CONSTRAINT "FK_HistorialPuestos_Empleados_IdEmpleado" FOREIGN KEY ("IdEmpleado") REFERENCES "Empleados" ("IdEmpleado") ON DELETE CASCADE
);

CREATE TABLE "TrayectoriaEmpleado" (
    "IdHistorialLaboral" integer GENERATED BY DEFAULT AS IDENTITY,
    "EmpleadoIdEmpleado" integer NOT NULL,
    "FechaCambio" timestamp with time zone NOT NULL,
    "TipoCambio" character varying(100) NOT NULL,
    "PuestoAnterior" character varying(100),
    "PuestoNuevo" character varying(100),
    "SalarioAnterior" numeric(18,2),
    "SalarioNuevo" numeric(18,2),
    "DepartamentoAnterior" character varying(100),
    "DepartamentoNuevo" character varying(100),
    "MotivoCambio" character varying(500),
    "RegistradoPor" character varying(100),
    "FechaRegistro" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_TrayectoriaEmpleado" PRIMARY KEY ("IdHistorialLaboral"),
    CONSTRAINT "FK_TrayectoriaEmpleado_Empleados_EmpleadoIdEmpleado" FOREIGN KEY ("EmpleadoIdEmpleado") REFERENCES "Empleados" ("IdEmpleado") ON DELETE CASCADE
);

