CREATE TABLE "Incapacidades" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "IdEmpleado" integer NOT NULL,
    "FechaInicio" timestamp with time zone NOT NULL,
    "FechaFin" timestamp with time zone NOT NULL,
    "Motivo" text NOT NULL,
    "Comentarios" text NOT NULL,
    "CreatedBy" character varying(100),
    "CreatedAt" timestamp with time zone NOT NULL,
    "LastModifiedBy" character varying(100),
    "LastModifiedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_Incapacidades" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Incapacidades_Empleados_IdEmpleado" FOREIGN KEY ("IdEmpleado") REFERENCES "Empleados" ("IdEmpleado") ON DELETE CASCADE
);

CREATE TABLE "Permisos" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "IdEmpleado" integer NOT NULL,
    "FechaSolicitud" timestamp with time zone NOT NULL,
    "FechaInicio" timestamp with time zone NOT NULL,
    "FechaFin" timestamp with time zone NOT NULL,
    "Motivo" text NOT NULL,
    "Aprobado" boolean NOT NULL,
    "Comentarios" text NOT NULL,
    "CreatedBy" character varying(100),
    "CreatedAt" timestamp with time zone NOT NULL,
    "LastModifiedBy" character varying(100),
    "LastModifiedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_Permisos" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Permisos_Empleados_IdEmpleado" FOREIGN KEY ("IdEmpleado") REFERENCES "Empleados" ("IdEmpleado") ON DELETE CASCADE
